<?php
declare(strict_types=1);require_once __DIR__.'/includes/bootstrap.php';$month=(string)($_GET['month']??date('Y-m'));if(!valid_month($month))$month=date('Y-m');$start=$month.'-01';$end=date('Y-m-d',strtotime($start.' +1 month'));$s=$pdo->prepare('SELECT type,category,SUM(amount) total,COUNT(*) n FROM transactions WHERE transaction_date>=:s AND transaction_date<:e GROUP BY type,category ORDER BY type,total DESC');$s->execute(['s'=>$start,'e'=>$end]);$rows=$s->fetchAll();$income=0.0;$expense=0.0;$ins=[];$outs=[];foreach($rows as $r){if($r['type']==='income'){$income+=(float)$r['total'];$ins[]=$r;}else{$expense+=(float)$r['total'];$outs[]=$r;}}$pageTitle='Reports — ExpenseWise';require __DIR__.'/includes/header.php';?><div class="app-shell"><?php require __DIR__.'/includes/sidebar.php';?><main class="main-area"><header class="topbar"><div><p class="breadcrumb">Workspace / Reports</p><h1>Your month, in perspective.</h1></div></header><section class="month-toolbar"><div><span class="eyebrow">MONTHLY REPORT</span><p>Compare income and spending by category.</p></div><form class="month-picker"><label for="month">Month</label><input id="month" type="month" name="month" value="<?=e($month)?>"><button class="button soft">View</button></form></section><section class="summary-grid"><article class="summary-card"><span>Total income</span><strong><?=money($income)?></strong><small>Selected month</small></article><article class="summary-card"><span>Total expenses</span><strong><?=money($expense)?></strong><small>Selected month</small></article><article class="summary-card balance"><span>Net balance</span><strong><?=money($income-$expense)?></strong><small>Income minus expenses</small></article><article class="summary-card"><span>Categories used</span><strong><?=count($rows)?></strong><small>Income and expenses</small></article></section><section class="content-grid"><article class="panel recent"><div class="panel-heading"><div><h2>Expense categories</h2><p><?=e(date('F Y',strtotime($start)))?></p></div></div><?php if(!$outs):?><div class="empty"><strong>No expense data yet.</strong><p>Add expenses to build your report.</p></div><?php else:?><div class="table-scroll"><table><thead><tr><th>CATEGORY</th><th>TRANSACTIONS</th><th class="right">TOTAL</th></tr></thead><tbody><?php foreach($outs as $r):?><tr><td><span class="pill"><?=e($r['category'])?></span></td><td><?=(int)$r['n']?></td><td class="right"><?=money((float)$r['total'])?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></article><article class="panel recent"><div class="panel-heading"><div><h2>Income sources</h2><p>Where money came from</p></div></div><?php if(!$ins):?><div class="empty"><strong>No income data yet.</strong><p>Add income to see a breakdown.</p></div><?php else:?><div class="table-scroll"><table><thead><tr><th>SOURCE</th><th>TRANSACTIONS</th><th class="right">TOTAL</th></tr></thead><tbody><?php foreach($ins as $r):?><tr><td><span class="pill"><?=e($r['category'])?></span></td><td><?=(int)$r['n']?></td><td class="right green"><?=money((float)$r['total'])?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></article></section><footer class="app-footer">ExpenseWise <span>Personal finance, made clearer.</span></footer></main></div><?php require __DIR__.'/includes/footer.php';?>
